alter table public.topics add column if not exists is_featured boolean not null default false;
alter table public.topics add column if not exists featured_order smallint;
alter table public.topics add column if not exists original_title text;
alter table public.topics add column if not exists original_body text;
create unique index if not exists topics_featured_order_uidx on public.topics(featured_order) where is_featured=true;
create index if not exists topics_featured_idx on public.topics(is_featured,featured_order) where status='published';
drop policy if exists answers_insert_audience on public.answers;
create policy answers_insert_audience on public.answers for insert to authenticated with check(user_id=auth.uid() and status='published' and is_editorial=false and editorial_key is null and exists(select 1 from public.topics t join public.profiles p on p.id=auth.uid() where t.id=topic_id and t.status='published' and (not t.is_timed or t.expires_at>now()) and (t.audience='all' or t.audience=p.gender)));
alter table public.reports drop constraint if exists reports_target_type_check;
alter table public.reports add constraint reports_target_type_check check(target_type in('story','comment','user','topic','answer'));
